156	/* ── Status badges ────────────────────────────────────────────────────────── */
157	.badge-running  { background:#FF6B35; color:#fff; padding:2px 8px; border-radius:4px; font-size:11px; }
158	.badge-completed{ background:#4CAF50; color:#fff; padding:2px 8px; border-radius:4px; font-size:11px; }
159	.badge-failed   { background:#E84545; color:#fff; padding:2px 8px; border-radius:4px; font-size:11px; }
160	.badge-cancelled{ background:#9090A8; color:#fff; padding:2px 8px; border-radius:4px; font-size:11px; }
161	</style>
162	"""
163	
164	
165	def inject_css() -> None:
166	    """Inject the shared CSS block into the current Streamlit page."""
167	    st.markdown(CSS, unsafe_allow_html=True)
168	
169	
170	def score_color(score: float) -> str:
171	    """Return a hex color for a [0,1] score (red → yellow → green)."""
172	    if score >= 0.75:
173	        return SUCCESS
174	    if score >= 0.45:
175	        return WARNING
176	    return PRIMARY
177	
178	
179	def badge(status: str) -> str:
