199	        <div style='background:#2A2A3E;border-radius:8px;padding:0.7rem 1rem;margin-bottom:0.5rem'>
200	          <div style='font-size:12px;color:#9090A8'>{label}</div>
201	          <div style='font-size:22px;font-weight:700;color:#FF6B35'>{value}</div>
202	          {delta_html}
203	        </div>
204	        """,
205	        unsafe_allow_html=True,
206	    )
